160→// fetchLatestVersion fetches the latest version from the GitHub API.
161→// Returns a timeout-safe version check using the configured HTTP timeout.
162→func fetchLatestVersion() (string, error) {
163→	// Create a context with timeout for the HTTP request
164→	ctx, cancel := context.WithTimeout(context.Background(), httpTimeout)
165→	defer cancel()
166→
167→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
168→	if err != nil {
169→		return "", fmt.Errorf("creating request: %w", err)
170→	}
171→
172→	// Set headers to identify as Entire CLI
173→	req.Header.Set("Accept", "application/vnd.github+json")
174→	req.Header.Set("User-Agent", "entire-cli")
175→
176→	client := &http.Client{}
177→	resp, err := client.Do(req)
178→	if err != nil {
179→		return "", fmt.Errorf("fetching release info: %w", err)
180→	}
181→	defer resp.Body.Close()
182→
183→	if resp.StatusCode != http.StatusOK {
184→		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
185→	}
186→
187→	// Read response body (limit to 1MB to prevent memory exhaustion)
188→	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
189→	if err != nil {
190→		return "", fmt.Errorf("reading response: %w", err)
191→	}
192→
193→	// Parse GitHub release response
194→	version, err := parseGitHubRelease(body)
195→	if err != nil {
196→		return "", fmt.Errorf("parsing release: %w", err)
197→	}
198→
199→	return version, nil
200→}
