202→// parseGitHubRelease parses the GitHub API response and extracts the latest stable version.
203→// Filters out prerelease versions.
204→func parseGitHubRelease(body []byte) (string, error) {
205→	var release GitHubRelease
206→	if err := json.Unmarshal(body, &release); err != nil {
207→		return "", fmt.Errorf("parsing JSON: %w", err)
208→	}
209→
210→	// Skip prerelease versions
211→	if release.Prerelease {
212→		return "", errors.New("only prerelease versions available")
213→	}
214→
215→	// Ensure we have a tag name
216→	if release.TagName == "" {
217→		return "", errors.New("empty tag name")
218→	}
219→
220→	return release.TagName, nil
221→}
